using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;using ESRI.ArcGIS;using ESRI.ArcGIS.Carto;using ESRI.ArcGIS.Geodatabase;using ESRI.ArcGIS.esriSystem;
public static class NativeAudit{[System.Runtime.InteropServices.DllImport("user32.dll")] static extern IntPtr GetDesktopWindow();
 public static void Run(string mxd,string config,string report){RuntimeManager.Bind(ProductCode.Desktop);IAoInitialize lic=new AoInitializeClass();lic.Initialize(esriLicenseProductCode.esriLicenseProductCodeAdvanced);JavaScriptSerializer js=new JavaScriptSerializer();js.MaxJsonLength=Int32.MaxValue;var cfg=js.Deserialize<Dictionary<string,object>>(File.ReadAllText(config));var scientific=(Dictionary<string,object>)cfg["scientific_metadata"];int expected=Convert.ToInt32(scientific["baseline_n"]);var specs=new Dictionary<string,Dictionary<string,object>>();foreach(object s in(ArrayList)scientific["raw_specs"]){var a=(Dictionary<string,object>)s;specs[Convert.ToString(a["field"])]=a;}IMapDocument d=new MapDocumentClass();d.Open(mxd,"");for(int ai=0;ai<d.MapCount;ai++)((IActiveView)d.get_Map(ai)).Activate(GetDesktopWindow().ToInt32());((IActiveView)d.PageLayout).Activate(GetDesktopWindow().ToInt32());if(d.MapCount!=6)throw new Exception("Wrong map count");var rows=new ArrayList();
 for(int mi=0;mi<d.MapCount;mi++){IMap m=d.get_Map(mi);string field=m.Name.Substring("panel_".Length);var sp=specs[field];IGeoFeatureLayer found=null;for(int li=0;li<m.LayerCount;li++){ILayer layer=m.get_Layer(li);if(!layer.Valid)throw new Exception("Broken layer "+m.Name+"/"+layer.Name);IGeoFeatureLayer gl=layer as IGeoFeatureLayer;if(gl!=null&&gl.Renderer is IClassBreaksRenderer)found=gl;}if(found==null)throw new Exception("Missing continuous field");IClassBreaksRenderer r=(IClassBreaksRenderer)found.Renderer;if(r.Field!="display_"+field||r.BreakCount!=128||r.MinimumBreak!=0||r.get_Break(127)!=1)throw new Exception("Wrong display renderer");IQueryFilter q=new QueryFilterClass();q.WhereClause=((IFeatureLayerDefinition)found).DefinitionExpression;IFeatureClass fc=found.FeatureClass;int n=fc.FeatureCount(q);if(n!=expected)throw new Exception("Common mask count mismatch");IFeatureCursor cur=fc.Search(q,true);IFeature f;double lo=Double.PositiveInfinity,hi=Double.NegativeInfinity;int idx=fc.FindField(field),di=fc.FindField("display_"+field);double maxerr=0;while((f=cur.NextFeature())!=null){double v=Convert.ToDouble(f.get_Value(idx));double col=Convert.ToDouble(f.get_Value(di));lo=Math.Min(lo,v);hi=Math.Max(hi,v);double a=Convert.ToDouble(sp["display_min_raw"]),b=Convert.ToDouble(sp["display_max_raw"]);double want=Convert.ToString(sp["display_transform"])=="log10_1p"?(Math.Log10(1+v)-Math.Log10(1+a))/(Math.Log10(1+b)-Math.Log10(1+a)):(v-a)/(b-a);maxerr=Math.Max(maxerr,Math.Abs(want-col));}System.Runtime.InteropServices.Marshal.ReleaseComObject(cur);if(lo!=Convert.ToDouble(sp["observed_min"])||hi!=Convert.ToDouble(sp["observed_max"])||maxerr>1e-12)throw new Exception("Raw min/max or display transformed wrong");rows.Add(new{map=m.Name,field=field,n=n,observed_min=lo,observed_max=hi,display_error=maxerr,renderer_steps=128,source=((IDataset)fc).Workspace.PathName,feature_class=((IDataset)fc).Name});}
 File.WriteAllText(report,js.Serialize(new{status="PASS",engine="Native ArcObjects Desktop10.8",mxd=mxd,common_n=expected,all_six_maps_correct=true,models_recomputed=false,checks=rows}));d.Close();lic.Shutdown();Console.WriteLine("PASS_NATIVE_DATA_AUDIT "+mxd);
 }
}
